// Generates src/agent/prompt-text.generated.ts from spec/prompts.md (every <!-- measure: id --> block).
// Run: bun scripts/gen-prompts.ts
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dir, "..");
const md = readFileSync(join(root, "spec/prompts.md"), "utf8");
const re = /<!-- measure: (\w+) -->\n(~~~~|```)\w*\n([\s\S]*?)\n\2\n/g;
const out: Record<string, string> = {};
for (const m of md.matchAll(re)) out[m[1]] = m[3];
const body =
  "// GENERATED by scripts/gen-prompts.ts from spec/prompts.md. Do not edit by hand.\n" +
  "export const PROMPT_TEXT = " + JSON.stringify(out, null, 2) + " as const;\n";
writeFileSync(join(root, "src/agent/prompt-text.generated.ts"), body);
console.log(`wrote ${Object.keys(out).length} blocks`);
